#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum HostAccessOutcome {
    HostAccessGrounded {
        principal: Rc<GroundedPosixPrincipal>,
    },
    HostAccessAccountNotGrounded {
        account_outcome: Rc<GroundedPosixPrincipalOutcome>,
    },
    HostAccessKeyPopulationDrifted {
        expected: Rc<Vec<Rc<SshPublicKey>>>,
        observed: Rc<Vec<Rc<SshPublicKey>>>,
    },
    HostAccessPasswordLoginStillAdmitted,
    HostAccessPrivilegeNotProven,
}

pub fn ground_host_access(intent: Rc<FleetPrincipalIntent>, standing: Rc<PosixAccountAllocationStanding>, access: Rc<PosixAccessObservation>) -> Rc<HostAccessOutcome> {
    {
        let account = ground_posix_principal(intent, standing, Some(access.account.clone()));
match (*account.clone()).clone() {
    GroundedPosixPrincipalOutcome::PrincipalGrounded { principal: p, .. } => if !access.password_login_refused.clone() {
            Rc::new(HostAccessOutcome::HostAccessPasswordLoginStillAdmitted)
        } else {
            if !access.privileged_probe_succeeded.clone() {
                Rc::new(HostAccessOutcome::HostAccessPrivilegeNotProven)
            } else {
                Rc::new(HostAccessOutcome::HostAccessGrounded {
    principal: p.clone(),
})
            }
        },
    GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope { principal: _, .. } => Rc::new(HostAccessOutcome::HostAccessAccountNotGrounded {
    account_outcome: account.clone(),
}),
    GroundedPosixPrincipalOutcome::PrincipalUnallocated { occurrence: _, .. } => Rc::new(HostAccessOutcome::HostAccessAccountNotGrounded {
    account_outcome: account.clone(),
}),
    GroundedPosixPrincipalOutcome::PrincipalAllocationConflicted { .. } => Rc::new(HostAccessOutcome::HostAccessAccountNotGrounded {
    account_outcome: account.clone(),
}),
    GroundedPosixPrincipalOutcome::PrincipalUnobserved { allocation: _, .. } => Rc::new(HostAccessOutcome::HostAccessAccountNotGrounded {
    account_outcome: account.clone(),
}),
    GroundedPosixPrincipalOutcome::PrincipalDrifted { .. } => Rc::new(HostAccessOutcome::HostAccessAccountNotGrounded {
    account_outcome: account.clone(),
}),
}
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum GroundedPosixPrincipalOutcome {
    PrincipalGrounded {
        principal: Rc<GroundedPosixPrincipal>,
    },
    PrincipalRequiresHostScope {
        principal: FleetPosixAccountKey,
    },
    PrincipalUnallocated {
        occurrence: Rc<PosixAccountOccurrence>,
    },
    PrincipalAllocationConflicted {
        occurrence: Rc<PosixAccountOccurrence>,
        first: Rc<PosixAccountAllocationConflict>,
        more: Rc<Vec<Rc<PosixAccountAllocationConflict>>>,
    },
    PrincipalUnobserved {
        allocation: Rc<PosixAccountAllocation>,
    },
    PrincipalDrifted {
        allocation: Rc<PosixAccountAllocation>,
        first: Rc<PosixAccountConflict>,
        more: Rc<Vec<Rc<PosixAccountConflict>>>,
    },
}

pub fn ground_posix_principal(intent: Rc<FleetPrincipalIntent>, standing: Rc<PosixAccountAllocationStanding>, observation: Option<Rc<PosixAccountObservation>>) -> Rc<GroundedPosixPrincipalOutcome> {
    match (*standing.clone()).clone() {
    PosixAccountAllocationStanding::AccountUnallocated { occurrence: occ, .. } => Rc::new(GroundedPosixPrincipalOutcome::PrincipalUnallocated {
    occurrence: occ.clone(),
}),
    PosixAccountAllocationStanding::AccountAllocationConflict { occurrence: occ, first: f, more: m, .. } => Rc::new(GroundedPosixPrincipalOutcome::PrincipalAllocationConflicted {
    occurrence: occ.clone(),
    first: f.clone(),
    more: m.clone(),
}),
    PosixAccountAllocationStanding::AccountAllocated { allocation: a, .. } => match observation.clone() {
    std::option::Option::None => Rc::new(GroundedPosixPrincipalOutcome::PrincipalUnobserved {
    allocation: a.clone(),
}),
    Some(o) => if (o.occurrence.host.clone() != a.occurrence.host.clone()) {
        Rc::new(GroundedPosixPrincipalOutcome::PrincipalDrifted {
    allocation: a.clone(),
    first: Rc::new(PosixAccountConflict::ObservationSubjectMismatch {
    observed_host: o.occurrence.host.clone(),
    allocated_host: a.occurrence.host.clone(),
}),
    more: Rc::new(vec![]),
})
    } else {
        if (o.observed_user.name.clone() != a.local_name.clone()) {
            Rc::new(GroundedPosixPrincipalOutcome::PrincipalDrifted {
    allocation: a.clone(),
    first: Rc::new(PosixAccountConflict::ObservedNameDiffersFromAllocation {
    observed: o.observed_user.name.clone(),
    allocated: a.local_name.clone(),
}),
    more: Rc::new(vec![]),
})
        } else {
            if (o.observed_user.uid.clone() != a.uid.clone()) {
                Rc::new(GroundedPosixPrincipalOutcome::PrincipalDrifted {
    allocation: a.clone(),
    first: Rc::new(PosixAccountConflict::ObservedUidDiffersFromAllocation {
    observed: o.observed_user.uid.clone(),
    allocated: a.uid.clone(),
}),
    more: Rc::new(vec![]),
})
            } else {
                Rc::new(GroundedPosixPrincipalOutcome::PrincipalGrounded {
    principal: Rc::new(GroundedPosixPrincipal {
    posix: o.observed_user.clone(),
    sudo_grants: intent.sudo_grants.clone(),
    declared_probe: Rc::new(PosixAccountDeclaredProbe {
    probed_at: o.observed_at.clone(),
    probe_command: v1_rt::concat("id ".to_string(), o.observed_user.name.clone()),
    host: a.occurrence.host.clone(),
}),
}),
})
            }
        }
    },
},
}
}

