pub fn fleet_posix_legacy_principal(key: FleetPosixAccountKey) -> Option<Rc<GroundedPosixPrincipal>> {
    match (*fleet_posix_principal(key)).clone() {
    GroundedPosixPrincipalOutcome::PrincipalGrounded { principal: p, .. } => Some(p.clone()),
    GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope { principal: _, .. } => std::option::Option::None,
    GroundedPosixPrincipalOutcome::PrincipalUnallocated { occurrence: _, .. } => std::option::Option::None,
    GroundedPosixPrincipalOutcome::PrincipalAllocationConflicted { .. } => std::option::Option::None,
    GroundedPosixPrincipalOutcome::PrincipalUnobserved { allocation: _, .. } => std::option::Option::None,
    GroundedPosixPrincipalOutcome::PrincipalDrifted { .. } => std::option::Option::None,
}
}

pub fn fleet_posix_principal(key: FleetPosixAccountKey) -> Rc<GroundedPosixPrincipalOutcome> {
    match key.clone() {
    FleetPosixAccountKey::FleetAccountRoot => Rc::new(GroundedPosixPrincipalOutcome::PrincipalGrounded {
    principal: Rc::new(GroundedPosixPrincipal {
    posix: fleet_posix_root_user(),
    sudo_grants: fleet_posix_root_sudo_grants(),
    declared_probe: fleet_posix_root_declared_probe(),
}),
}),
    FleetPosixAccountKey::FleetAccountOperator => Rc::new(GroundedPosixPrincipalOutcome::PrincipalGrounded {
    principal: Rc::new(GroundedPosixPrincipal {
    posix: fleet_posix_operator_user(),
    sudo_grants: fleet_posix_operator_sudo_grants(),
    declared_probe: fleet_posix_operator_declared_probe(),
}),
}),
    FleetPosixAccountKey::FleetAccountCiRunner => Rc::new(GroundedPosixPrincipalOutcome::PrincipalGrounded {
    principal: Rc::new(GroundedPosixPrincipal {
    posix: fleet_posix_ci_runner_user(),
    sudo_grants: fleet_posix_ci_runner_sudo_grants(),
    declared_probe: fleet_posix_ci_runner_declared_probe(),
}),
}),
    FleetPosixAccountKey::FleetAccountHostAdministrator => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountAutomation => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountInferenceService => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountPublicationHelper => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountNotificationService => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountDeployJob => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
    FleetPosixAccountKey::FleetAccountRunnerListener => Rc::new(GroundedPosixPrincipalOutcome::PrincipalRequiresHostScope {
    principal: key.clone(),
}),
}
}

pub fn fleet_deploy_job_principal(runner: Rc<DeployRunnerPrincipal>) -> Option<Rc<GroundedPosixPrincipal>> {
    fleet_posix_account_from_name(runner.job_user.clone())
}

pub fn grounded_posix_principal_name(p: Rc<GroundedPosixPrincipal>) -> String {
    p.posix.name.clone()
}

pub fn posix_declared_probe_names_principal(p: Rc<GroundedPosixPrincipal>) -> bool {
    {
        let expected = v1_rt::concat("id ".to_string(), p.posix.name.clone());
(p.declared_probe.probe_command.clone() == expected.clone())
}
}

pub fn fleet_posix_account_from_name(name: String) -> Option<Rc<GroundedPosixPrincipal>> {
    match (name.clone() == fleet_posix_root_user().name.clone()) {
    true => Some(fleet_posix_root_principal()),
    false => match (name.clone() == fleet_posix_operator_user().name.clone()) {
    true => Some(fleet_posix_operator_principal()),
    false => match (name.clone() == fleet_posix_ci_runner_user().name.clone()) {
    true => Some(fleet_posix_ci_runner_principal()),
    false => std::option::Option::None,
},
},
}
}

pub fn fleet_posix_account_exists_predicate_disposition() -> Rc<Disposition> {
    thread_local! {
        static CACHED: Rc<Disposition> = {
            Rc::new(Disposition::Scaffold {
    dissolves_to: ConstructionMechanism::SingleAuthority,
    bind: Rc::new(DeclarationRef {
    module_path: "gunbc.fleet.fleet_posix_accounts".to_string(),
    decl_name: "fleet_posix_account_from_name".to_string(),
    field: Rc::new(DeclField::WholeDeclaration),
}),
})
        };
    }
    CACHED.with(|c: &Rc<Disposition>| c.clone())
}

pub fn fleet_posix_account_exists(name: String) -> bool {
    match fleet_posix_account_from_name(name) {
    Some(_) => true,
    std::option::Option::None => false,
}
}

