pub fn reported_contradiction_is_open(c: Rc<ReportedAccountContradiction>) -> bool {
    ((c.modeled_uid.clone() != c.reported_uid.clone()) || (c.modeled_gid.clone() != c.reported_gid.clone()))
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum FleetAutomationAllocationStanding {
    AutomationAllocationApplied {
        host: HostIdentity,
        user: Rc<PosixUser>,
        source: NonEmptyStr,
    },
    AutomationAllocationPending {
        host: HostIdentity,
        cause: NonEmptyStr,
    },
}
impl FleetAutomationAllocationStanding {
    pub fn host(&self) -> HostIdentity {
        match self {
            FleetAutomationAllocationStanding::AutomationAllocationApplied { host: __val, .. } => __val.clone(),
            FleetAutomationAllocationStanding::AutomationAllocationPending { host: __val, .. } => __val.clone(),
        }
    }
}

pub fn fleet_automation_user() -> Rc<PosixUser> {
    thread_local! {
        static CACHED: Rc<PosixUser> = {
            serde_json::from_str("{\"name\": \"gunbc-fleet\", \"uid\": 1001, \"gid\": 1001, \"shell\": {\"_variant\": \"LoginShellObserved\", \"path\": \"/bin/bash\"}}")
                .expect("valid data definition")
        };
    }
    CACHED.with(|c: &Rc<PosixUser>| c.clone())
}

pub fn fleet_automation_allocations() -> Rc<Vec<Rc<FleetAutomationAllocationStanding>>> {
    Rc::new(vec![Rc::new(FleetAutomationAllocationStanding::AutomationAllocationApplied {
    host: "srv1".to_string(),
    user: fleet_automation_user(),
    source: "witty-raven-412 msg_f7cbef82; password LOCKED, sudo NONE verified, authorized_keys 0600 single line".to_string(),
}), Rc::new(FleetAutomationAllocationStanding::AutomationAllocationApplied {
    host: "srv2".to_string(),
    user: fleet_automation_user(),
    source: "witty-raven-412 msg_f7cbef82; password LOCKED, sudo NONE verified, authorized_keys 0600 single line".to_string(),
}), Rc::new(FleetAutomationAllocationStanding::AutomationAllocationPending {
    host: "srv3".to_string(),
    cause: "host unreachable from the allocating session; key refused at its address".to_string(),
}), Rc::new(FleetAutomationAllocationStanding::AutomationAllocationPending {
    host: "srv4".to_string(),
    cause: "no address available to the allocating session".to_string(),
})])
}

pub fn automation_allocation_is_applied(a: Rc<FleetAutomationAllocationStanding>) -> bool {
    match (*a.clone()).clone() {
    FleetAutomationAllocationStanding::AutomationAllocationApplied { .. } => true,
    FleetAutomationAllocationStanding::AutomationAllocationPending { .. } => false,
}
}

pub fn fleet_posix_home_directory(login: String) -> String {
    Rc::new(vec!["/home/".to_string(), login.clone()]).join(&"".to_string())
}

